const gallery = document.querySelector('[data-testid="zimm-product-gallery"]');
const row = gallery.parentElement; // the flex row with gap:180px we already found
const contentCol = Array.from(row.children).find(c => c !== gallery);
const outerWrapper = row.parentElement;
function styleInfo(el, props) {
  if (!el) return null;
  const cs = getComputedStyle(el);
  const out = {};
  props.forEach(p => out[p] = cs[p]);
  out.rect = el.getBoundingClientRect();
  out.tag = el.tagName; out.cls = el.className;
  return out;
}
JSON.stringify({
