}, [selectedStore]);

const handleDeliveryOptionChange = (value: string) => {
  setPickupInStore(value === DELIVERY_OPTIONS.PICKUP);
};

return (
  <Flex
    direction={'column'}
    data-testid="product-view"
    ref={ref}
    // SFCC-731 — 140px right / 40px bottom, per Figma "pdp/hero" (node 7932:45339).
    // On the outer wrapper (not the row below) so it applies to the whole product area.
    pr={[0, 0, 0, 'var(--zimm-scale-3500)']}
    pb={[0, 0, 0, 'var(--zimm-scale-1000)']}
  >
    {/*
     * Basic information etc. title, price, breadcrumb — base behaviour, shown above the
     * gallery on mobile/tablet. SFCC-731 scopes this to imageSize="sm" callers only
     * (product-view-modal's quick-view/bundle paths, bonus-product-view-modal), which keep
     * this exactly as the base file always has it. The PDP's own path (imageSize="md", the
     * default) never shows this block — the confirmed Figma compact frames put the gallery
     * unambiguously first, with no header content ahead of it at any breakpoint; the PDP's
     * own header instead always renders after the gallery (see the content column's own
     * `display` below, mirroring this same imageSize condition).
     */}
    {imageSize === 'sm' && (
      <Box display={['block', 'block', 'block', 'none']}>
        {renderHeader({
          name: product?.name,
          product,
          priceData,
          currency: product?.currency || activeCurrency,
          category,
          isProductPartOfBundle,
        })}
      </Box>
    )}
    {/* SFCC-731 — 180px gap between gallery/content at `lg`+, 32px stacked below. */}
    <Flex
      direction={['column', 'column', 'column', 'row']}
      gap={['var(--zimm-scale-800)', 'var(--zimm-scale-800)', 'var(--zimm-scale-800)', 'var(--zimm-scale-4500)']}
    >
      {/* minWidth={0} overrides the flex item default of `auto` on the Box below — without
          it, a flex item's content can set an implicit minimum that keeps it from shrinking
          to make room for a sibling with a competing width, even under flex:1. */}
      {showImageGallery && (
        <Box flex={1} minWidth={0}>
          {product ? (
            <>
              {imageSize === 'sm' ? (
                <ImageGallery
                  size={imageSize}
                  imageGroups={product.imageGroups}
                  selectedVariationAttributes={variationParams}
                  lazy={isProductPartOfSet || isProductPartOfBundle}
                />
              ) : (
                <>
                  <ZimmProductGallery
                    media={mapImageGroupsToGalleryMedia(product.imageGroups, variationParams)}
                    lazy={isProductPartOfSet || isProductPartOfBundle}
                    onOpenGallery={() => setIsGalleryOverlayOpen(true)}
                  />
                  <ZimmGalleryOverlay
                    isOpen={isGalleryOverlayOpen}
                    onClose={() => setIsGalleryOverlayOpen(false)}
                    productName={product.name ?? ''}
                    media={mapImageGroupsToGalleryMedia(product.imageGroups, variationParams)}
                    colourValues={colourValues}
                    selectedColourValue={selectedColourValue}
                  />
                </>
              )}
              <HideOnMobile>
                {showFullLink && product && (
                  <Link to={`/product/${product.master.masterId}`} color="blue.600">
                    <FormattedMessage id="product_view.link.full_details" defaultMessage="See full details" />
                  </Link>
                )}
              </HideOnMobile>
            </>
          ) : imageSize === 'sm' ? (
            <ImageGallerySkeleton size={imageSize} />
          ) : (
            <AspectRatio ratio={GALLERY_ITEM_ASPECT_RATIO} data-testid="zimm-product-gallery-skeleton">
              <Skeleton />
            </AspectRatio>
          )}
          {/* Custom footer content (e.g., Back to Selection button) */}
          {imageGalleryFooter && (
            <Box mt={6} mb={2}>
              {imageGalleryFooter}
            </Box>
          )}
        </Box>
      )}

      {/* Variations & Quantity Selector & CTA buttons */}
      {/*
       * SFCC-731 deviation from the base file (was `flex={1}`, matching the base
       * `product-view/index.jsx:636-638` layout where both columns grow proportionally):
       * the confirmed Figma spec pins this column to a fixed width at `lg` and up, while
       * the gallery column grows fluidly to fill the rest — see the Flex's own gap/pr
       * comment above. Below `lg` this stays full-width, matching the stacked mobile/tablet
       * frames' `pdp/product-content` block.
       * audit-allow: 218px is a confirmed Figma measurement (PDP hero content column,
       * node 40000307:14476) — a page-composition width, not a spacing/gap value, so no
       * existing --zimm-scale-* token matches it.
       */}
      <VStack
        align="stretch"
        spacing={8}
        // Array, not the {base, lg} object form — matches every other responsive prop in
        // this file (e.g. `direction` above), and rules out any object-vs-array Chakra
        // resolution discrepancy as a variable. `flexBasis` set alongside `width` (both to
        // the same value) so the flex algorithm has an unambiguous main-size hint — with
        // only `width` set, a flex item's basis still defaults to `auto` before falling
        // back to `width`, which left this column free to claim more than 218px in
        // practice, starving the gallery's `flex={1}` sibling down to nothing.
        width={['100%', '100%', '100%', '218px']}
        flexBasis={['100%', '100%', '100%', '218px']}
        flexShrink={0}
        flexGrow={0}
        // Compact frames (mobile/tablet) show the gallery bleeding edge-to-edge with no
        // page-level padding, but `pdp/product-content` carries its own symmetric 32px
        // inset — this is a component-local concern, not something PageContainer's
        // page-level boxed={false} should apply uniformly (that would also pad the
        // gallery, which the Figma frames never show). Zeroed at `lg`+, where the Flex's
        // own `pr` (140px, see above) takes over instead.
        paddingX={['var(--zimm-scale-800)', 'var(--zimm-scale-800)', 'var(--zimm-scale-800)', 0]}
        // audit-allow: 120px verbatim from base product-view (index.jsx:636-638), unrelated
        // to this file's own SFCC-731 width/flexShrink/paddingX changes above — not a Figma value.
        pb={[
          isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
          isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
          isProductPartOfSet || isProductPartOfBundle ? 4 : '120px',
          4,
        ]}
      >

content.content:
    sx={styles.closeButton}
  />
);

