const cs = page ? getComputedStyle(page) : null;
const firstChild = page ? page.firstElementChild : null;
const csFirst = firstChild ? getComputedStyle(firstChild) : null;
JSON.stringify({
  url: location.href,
  pageRect: page ? page.getBoundingClientRect() : null,
  pagePaddingTop: cs ? cs.paddingTop : null,
  pagePaddingBottom: cs ? cs.paddingBottom : null,
  firstChildTag: firstChild ? firstChild.tagName : null,
  firstChildPaddingTop: csFirst ? csFirst.paddingTop : null,
  bodyScrollHeight: document.body.scrollHeight,
});

