  headerRect: header ? header.getBoundingClientRect() : null,
  pageTop: page ? page.getBoundingClientRect().top : null,
  pageBottom: page ? page.getBoundingClientRect().bottom : null,
  footerTop: footer ? footer.getBoundingClientRect().top : null,
  gapAboveHero_pageTopMinusHeaderBottom: (page && header) ? (page.getBoundingClientRect().top - header.getBoundingClientRect().bottom) : null,
